import org.gradle.api.tasks.testing.logging.TestExceptionFormat

plugins {
    kotlin("jvm") version "2.1.21"
}

repositories {
    mavenCentral()
}

// generated by scripts/bindings.sh kotlin
val bindings = rootDir.resolve("../../dist/bindings/kotlin")
// the directory of libkraken_ffi for the host: target/debug, built by scripts/bindings.sh
val libraryDir: String = providers.gradleProperty("krakenLibraryDir")
    .getOrElse(rootDir.resolve("../../target/debug").absolutePath)

sourceSets {
    main {
        kotlin.srcDir(bindings)
    }
}

dependencies {
    implementation("net.java.dev.jna:jna:5.17.0")
    implementation("org.jetbrains.kotlinx:kotlinx-coroutines-core:1.10.2")

    testImplementation("junit:junit:4.13.2")
    testImplementation("org.jetbrains.kotlinx:kotlinx-coroutines-test:1.10.2")
    testImplementation("com.squareup.okhttp3:mockwebserver:4.12.0")
}

tasks.compileKotlin {
    doFirst {
        check(bindings.resolve("uniffi").isDirectory) {
            "no bindings in $bindings: run scripts/bindings.sh kotlin"
        }
    }
}

tasks.test {
    systemProperty("jna.library.path", libraryDir)
    testLogging {
        events("passed", "skipped", "failed")
        exceptionFormat = TestExceptionFormat.FULL
    }
}
